// Fully standardized to English Core Blueprint & AGENTS.md guidelines

export const c12EngF8HtmlOverview = "\n<style>\n  p, li, div:not(.table-container):not(.table-responsive):not(.pt-scroll-wrapper):not(.mcq-option) {\n    text-align: justify !important;\n  }\n  h1, h2, h3, h4, h5, h6 { text-align: left; }\n  .text-center { text-align: center !important; }\n  .text-left { text-align: left !important; }\n</style>\n\n<div style=\"font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; line-height: 1.8; color: #E2E8F0; max-width: 950px; margin: 0 auto; padding: 12px; font-size: 15.5px;\">\n\n  <!-- Chapter Header Badge -->\n  <div style=\"background: linear-gradient(135deg, rgba(41, 182, 246, 0.22), rgba(2, 136, 209, 0.1)); border: 1.5px solid #29B6F6; border-radius: 12px; padding: 20px; margin-bottom: 25px; box-shadow: 0 4px 22px rgba(41, 182, 246, 0.15);\">\n    <div style=\"display: flex; align-items: center; gap: 10px; margin-bottom: 8px;\">\n      <span style=\"background: #29B6F6; color: #000; font-size: 12px; font-weight: 800; padding: 4px 10px; border-radius: 6px; letter-spacing: 0.5px;\">FLAMINGO &bull; PROSE CHAPTER 8</span>\n      <span style=\"color: #94A3B8; font-size: 13.5px; font-weight: 600;\">CLASS XII ENGLISH CORE</span>\n    </div>\n    <h1 style=\"color: #FFFFFF; font-size: 26px; font-weight: 900; margin: 0 0 6px 0; letter-spacing: -0.5px;\">Going Places</h1>\n    <p style=\"color: #CBD5E1; font-size: 15px; margin: 0; font-style: italic;\">\n      By A.R. Barton (Zurich, Switzerland) &mdash; Adolescent Fantasizing, Hero-Worship &amp; The Harsh Reality of Working-Class Life\n    </p>\n  </div>\n\n  <!-- Quick Glossary & Chapter Dossier Card -->\n  <div style=\"background: rgba(15, 23, 42, 0.92); border: 1.5px solid rgba(41, 182, 246, 0.4); border-radius: 10px; padding: 18px 20px; margin-bottom: 25px; box-shadow: 0 4px 20px rgba(0,0,0,0.35);\">\n    <h3 style=\"color: #29B6F6; font-size: 18px; margin: 0 0 12px 0; display: flex; align-items: center; gap: 8px;\">\n      <span>📖</span> Quick Glossary &amp; Chapter Dossier: Going Places\n    </h3>\n    <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; font-size: 14px; color: #CBD5E1;\">\n      <div><b style=\"color: #29B6F6;\">Author:</b> A.R. Barton (Contemporary Zurich-based Writer)</div>\n      <div><b style=\"color: #29B6F6;\">Protagonist:</b> Sophie (Imaginative daydreamer seeking escape from domestic drabness)</div>\n      <div><b style=\"color: #29B6F6;\">Character Foil:</b> Jansie (Pragmatic, sensible classmate accepting factory destiny)</div>\n      <div><b style=\"color: #29B6F6;\">Socioeconomic Destiny:</b> Earmarked for employment at the local biscuit factory</div>\n      <div><b style=\"color: #29B6F6;\">Geoff:</b> Sophie's taciturn elder brother, an apprentice mechanic inhabiting a mysterious world</div>\n      <div><b style=\"color: #29B6F6;\">Danny Casey:</b> Young Irish prodigy playing forward for United; the idol of Sophie's obsession</div>\n      <div><b style=\"color: #29B6F6;\">The Canal Bench:</b> Secluded spot where Sophie waits for Casey, confronting bitter disappointment</div>\n      <div><b style=\"color: #29B6F6;\">Core Theme:</b> Adolescent escapism, romantic hero-worship, and unyielding socioeconomic barriers</div>\n    </div>\n  </div>\n\n  <!-- Section 1: Executive Summary & Thematic Context -->\n  <h2 style=\"color: #29B6F6; font-size: 20px; font-weight: 800; border-bottom: 2px solid #29B6F6; padding-bottom: 6px; margin: 28px 0 16px 0;\">\n    1. Executive Summary &amp; Sociological Context\n  </h2>\n  <p>\n    In <b style=\"color: #29B6F6;\">Going Places</b>, contemporary writer <b style=\"color: #29B6F6;\">A.R. Barton</b> presents an incisive, empathetic psychological portrait of adolescent fantasizing, hero-worship, and the painful transition toward adulthood. Set against a gritty working-class British background, the story explores the inner emotional landscape of <b style=\"color: #29B6F6;\">Sophie</b>, a young schoolgirl who constructs elaborate daydreams to escape the suffocating domestic drudgery of her home and an inescapable future in a local biscuit factory.\n  </p>\n  <p>\n    Barton contrasts Sophie's unbridled romanticism with the pragmatic realism of her classmate <b style=\"color: #29B6F6;\">Jansie</b>. While Jansie maturely accepts their modest economic station, Sophie projects her romantic yearnings onto <b style=\"color: #29B6F6;\">Danny Casey</b>, an Irish football sensation. In doing so, Barton captures how underprivileged youth use celebrity hero-worship as a psychological sanctuary against socioeconomic mediocrity.\n  </p>\n\n  <!-- Section 2: Narrative Arc -->\n  <h2 style=\"color: #29B6F6; font-size: 20px; font-weight: 800; border-bottom: 2px solid #29B6F6; padding-bottom: 6px; margin: 28px 0 16px 0;\">\n    2. Deep Narrative Progression: Anatomy of an Adolescent Daydream\n  </h2>\n\n  <h3 style=\"color: #29B6F6; font-size: 17px; margin: 20px 0 10px 0;\">(i) Sophie vs. Jansie: Daydreams vs. Factory Reality</h3>\n  <p>\n    Walking home from school, the two adolescent friends reveal opposing outlooks on life:\n  </p>\n  <ul style=\"color: #CBD5E1; font-size: 14.5px; padding-left: 20px;\">\n    <li><b style=\"color: #29B6F6;\">Sophie (The Romantic Dreamer):</b> Yearns for glamour, fame, and wealth. She grandly announces that after school, she will open an ultra-chic boutique like Mary Quant, become an actress, a corporate manager, or a high-fashion designer. She refuses to acknowledge her economic boundaries.</li>\n    <li><b style=\"color: #29B6F6;\">Jansie (The Grounded Realist):</b> Pragmatic and melancholic. Jansie knows they are both earmarked for the local biscuit factory. She urges Sophie to be sensible, reminding her that opening a boutique requires immense capital that her poor family does not possess.</li>\n  </ul>\n\n  <h3 style=\"color: #29B6F6; font-size: 17px; margin: 20px 0 10px 0;\">(ii) The Working-Class Household &amp; Silence of Geoff</h3>\n  <p>\n    Sophie returns to her modest home, where her mother stands stooped over the sink in the steam-filled kitchen and dirty laundry is piled in the corner. Her father, a burly, sweat-stained laborer, unbuttons his boots before the television, sipping beer with cynical realism. Her younger brother, Derek, mocks her openly: <i>\"She thinks money grows on trees, don't she, Dad?\"</i>\n  </p>\n  <p>\n    Seeking an ally, Sophie seeks out her elder brother, <b style=\"color: #29B6F6;\">Geoff</b>. Geoff is an apprentice mechanic who has been out of school for three years. He travels daily to the far side of the city, speaks sparingly, and spends his evenings tinkering with his motorbike in greasy overalls. Sophie envies Geoff’s silence, imagining that in his quiet mind lies an exotic, glamorous world of unknown people and places from which she is excluded.\n  </p>\n\n  <h3 style=\"color: #29B6F6; font-size: 17px; margin: 20px 0 10px 0;\">(iii) The Fabricated Danny Casey Encounter</h3>\n  <p>\n    To capture Geoff’s attention and penetrate his inner circle, Sophie invents a dazzling story: she claims she met <b style=\"color: #29B6F6;\">Danny Casey</b>, the young Irish football prodigy playing for United, outside the Royce arcade window.\n  </p>\n  <p>\n    She provides vivid fictional details: Casey had gentle, shy green eyes, freckles, and spoke with a soft Irish lilt. She claimed they chatted, but when she asked for an autograph for little Derek, neither had a pen or paper. Crucially, she claimed Casey promised to meet her again the following week to give her the autograph.\n  </p>\n  <p>\n    When Geoff shares this revelation with their father, the father scoffs with contempt: <i>\"He don’t believe you. One of these days you’re going to talk yourself into a load of trouble.\"</i> The father warns her that many promising young players ruin their careers, dismissing her story as absurd nonsense.\n  </p>\n\n  <h3 style=\"color: #29B6F6; font-size: 17px; margin: 20px 0 10px 0;\">(iv) Saturday Stadium Pilgrimage: Public Athletic Worship</h3>\n  <p>\n    On Saturday, the family makes their weekly pilgrimage to watch United play. Surrounded by thousands of roaring fans, Sophie watches Danny Casey dazzle on the pitch. With exquisite grace and agility, Casey scores a sensational second goal, dodging defenders and beating the goalkeeper.\n  </p>\n  <p>\n    Her father screams with triumph and heads to the pub to celebrate. Sophie's adoration for Casey intensifies, further blurring the boundary between athletic reality and her private romantic obsession.\n  </p>\n\n  <h3 style=\"color: #29B6F6; font-size: 17px; margin: 20px 0 10px 0;\">(v) Fear of Exposure: Jansie's Confrontation</h3>\n  <p>\n    A few days later, Jansie confronts Sophie about the secret meeting with Danny Casey, as Geoff had casually mentioned it to her brother Frank. Sophie is horrified. She fears her delicate fantasy being broadcast across the neighborhood, causing her cynical father to erupt in fury. Realizing Geoff kept the promise of their date secret, she manages to placate Jansie by begging her to keep the matter quiet.\n  </p>\n\n  <h3 style=\"color: #29B6F6; font-size: 17px; margin: 20px 0 10px 0;\">(vi) The Canal Bench: Desolation &amp; Persistent Illusion</h3>\n  <p>\n    After dark, Sophie walks along the lonely canal path, lit only by lamps from the wharf across the water. She sits down on a wooden bench beneath a solitary elm tree &mdash; a quiet spot where lovers traditionally met.\n  </p>\n  <p>\n    She waits with breathless anticipation for Danny Casey to appear. As time ticks agonizingly away, the cold reality sets in: <b style=\"color: #29B6F6;\">he will not come</b>. She feels the heavy burden of sadness settling over her heart:\n    <br/>\n    <i>\"Now I have become sad, she thought. And it is a hard thing to bear, this sadness. People will doubt me. They will say they always knew it was a lie.\"</i>\n  </p>\n  <p>\n    Yet, as she walks back through the dark streets past Royce’s boutique, her resilient imagination takes flight once more. She envisions Danny Casey standing again outside the glass window, picturing his soft voice, shy green eyes, and the roaring stadium crowd cheering his glorious goal. She retreats back into her comforting world of illusions.\n  </p>\n\n  <!-- Section 3: Literary Devices Master Table -->\n  <h2 style=\"color: #29B6F6; font-size: 20px; font-weight: 800; border-bottom: 2px solid #29B6F6; padding-bottom: 6px; margin: 28px 0 16px 0;\">\n    3. Literary &amp; Rhetorical Devices Master Table\n  </h2>\n  <div style=\"overflow-x: auto; margin-bottom: 25px;\">\n    <table style=\"width: 100%; border-collapse: collapse; font-size: 14px; text-align: left; background: rgba(15, 23, 42, 0.9); border-radius: 8px; overflow: hidden;\">\n      <thead>\n        <tr style=\"background: rgba(41, 182, 246, 0.25); color: #FFFFFF; border-bottom: 2px solid #29B6F6;\">\n          <th style=\"padding: 12px 14px;\">Literary Device</th>\n          <th style=\"padding: 12px 14px;\">Textual Quote / Example</th>\n          <th style=\"padding: 12px 14px;\">Thematic Function &amp; Critical Impact</th>\n        </tr>\n      </thead>\n      <tbody>\n        <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.08);\">\n          <td style=\"padding: 10px 14px; font-weight: bold; color: #29B6F6;\">Character Foil</td>\n          <td style=\"padding: 10px 14px;\">Sophie (Uncurbed Dreamer) vs. Jansie (Pragmatic Realist)</td>\n          <td style=\"padding: 10px 14px; color: #CBD5E1;\">Highlights the tension between adolescent escapism and the unavoidable reality of working-class survival.</td>\n        </tr>\n        <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.08);\">\n          <td style=\"padding: 10px 14px; font-weight: bold; color: #29B6F6;\">Situational Irony</td>\n          <td style=\"padding: 10px 14px;\">Sophie waits by the canal bench, grieving over the absence of a hero she knew she had fabricated.</td>\n          <td style=\"padding: 10px 14px; color: #CBD5E1;\">Demonstrates the power of self-delusion where invented falsehoods produce genuine emotional heartbreak.</td>\n        </tr>\n        <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.08);\">\n          <td style=\"padding: 10px 14px; font-weight: bold; color: #29B6F6;\">Sensory Imagery</td>\n          <td style=\"padding: 10px 14px;\">\"Steam-filled kitchen, greasy motorcycle parts, the roaring stadium of fifty thousand fans.\"</td>\n          <td style=\"padding: 10px 14px; color: #CBD5E1;\">Creates sharp visceral contrast between domestic drabness and public athletic ecstasy.</td>\n        </tr>\n        <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.08);\">\n          <td style=\"padding: 10px 14px; font-weight: bold; color: #29B6F6;\">Symbolism</td>\n          <td style=\"padding: 10px 14px;\">The Canal Bench &amp; Royce's Boutique Window</td>\n          <td style=\"padding: 10px 14px; color: #CBD5E1;\">Represent the solitary borderland where adolescent desire meets cold, unyielding reality.</td>\n        </tr>\n        <tr>\n          <td style=\"padding: 10px 14px; font-weight: bold; color: #29B6F6;\">Psychological Realism</td>\n          <td style=\"padding: 10px 14px;\">\"Now I have become sad... And it is a hard thing to bear, this sadness.\"</td>\n          <td style=\"padding: 10px 14px; color: #CBD5E1;\">Captures the authentic melancholy and emotional devastation of a young girl waking from her illusions.</td>\n        </tr>\n      </tbody>\n    </table>\n  </div>\n\n  <!-- Section 4: Thematic Pillars -->\n  <h2 style=\"color: #29B6F6; font-size: 20px; font-weight: 800; border-bottom: 2px solid #29B6F6; padding-bottom: 6px; margin: 28px 0 16px 0;\">\n    4. Core Thematic Pillars &amp; Critical Insights\n  </h2>\n  <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 14px;\">\n    <div style=\"background: rgba(41, 182, 246, 0.08); border-left: 4px solid #29B6F6; padding: 14px; border-radius: 6px;\">\n      <h4 style=\"color: #FFFFFF; margin: 0 0 6px 0; font-size: 15.5px;\">Adolescent Escapism</h4>\n      <p style=\"margin: 0; color: #CBD5E1; font-size: 13.5px;\">Unable to accept a bleak future in a biscuit factory, Sophie invents dazzling fantasies of boutiques and celebrity love.</p>\n    </div>\n    <div style=\"background: rgba(41, 182, 246, 0.08); border-left: 4px solid #29B6F6; padding: 14px; border-radius: 6px;\">\n      <h4 style=\"color: #FFFFFF; margin: 0 0 6px 0; font-size: 15.5px;\">Hero-Worship &amp; Projection</h4>\n      <p style=\"margin: 0; color: #CBD5E1; font-size: 13.5px;\">Danny Casey becomes a vessel for Sophie’s unfulfilled emotional longings, blurring reality with romantic obsession.</p>\n    </div>\n    <div style=\"background: rgba(41, 182, 246, 0.08); border-left: 4px solid #29B6F6; padding: 14px; border-radius: 6px;\">\n      <h4 style=\"color: #FFFFFF; margin: 0 0 6px 0; font-size: 15.5px;\">Class Barriers &amp; Domestic Reality</h4>\n      <p style=\"margin: 0; color: #CBD5E1; font-size: 13.5px;\">The steam-filled kitchen, piled laundry, and cynical father underscore the unyielding boundaries of social class.</p>\n    </div>\n  </div>\n\n</div>\n";

